package ejemplos_bucles;

public class ejemplo1_while {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int numero=1;
		
		//Mientras que el numero sea menor o igual que 10
		//numero vale 1 y luego lo va sumando hasta valer 10
		while(numero<=10) {
			System.out.println(numero);
			numero++;
		}
		System.out.println("Fin del programa.");
	}

}
